//shikimori.io/uploads/poster/animes/3287/e3adbd7ea494b6f4847e5ab0925a9b59.jpeg",width:256,height:366},backdrop:{url:"https://shikimori.io/system/screenshots/original/d1845600bd45c42817c97f1773e4acd7e8b94f65.jpg",width:960,height:720}},episodes:1,catalogApproved:!0,catalogOnly:!1,audienceRating:1.89,malId:3287,image:"https://shikimori.io/uploads/poster/animes/3287/e3adbd7ea494b6f4847e5ab0925a9b59.jpeg",banner:"https://shikimori.io/system/screenshots/original/d1845600bd45c42817c97f1773e4acd7e8b94f65.jpg",detailsBanner:"https://shikimori.io/system/screenshots/original/d1845600bd45c42817c97f1773e4acd7e8b94f65.jpg",episodeNumbers:[1],episodeManifest:[{ordinal:1,season:1,audio:["kodik-1215"],tracks:[{id:"kodik-1215",label:"Fronda Studio",language:"ru",original:!1}]}]},{translations:{en:["",""],ja:["",""]},airedAt:null,relations:[],id:"mal-366",ids:{shikimori:366,mal:366,anilist:null,kodik:"serial-61459"},title:"Айка",originalTitle:"Aika",alt:"Агент Айка",description:"Катастрофическое землетрясение повергло Японию и большую часть страны под синие пучины океана. Почти 95% суши было поглощено солёными водами океанов и морей. Айка Сумэраги , главная героиня истории, является спасателем. Она исследует дно океана и ищет затерянные людьми драгоценности, различные технические разработки и всё то, что имеет материальную ценность и что не удалось спасти во время всемирного потопа. Но жизнь Айки кардинально меняется, когда она получает тайную и опасную миссию по поиску и возвращению секретного оружия, названного «Лагу». Девушка тогда ещё не знала, к чему приведёт эта миссия...",year:1997,type:"OVA",genres:["Экшен","Приключения","Комедия","Фантастика","этти"],rating:5.97,popularity:0,ongoing:!1,relatedMalIds:[],artwork:{poster:{url:"https://shikimori.io/uploads/poster/animes/366/073c01ac3f36949ca05df550ae82aa70.jpeg",width:420,height:600},backdrop:{url:"https://shikimori.io/system/screenshots/original/53178b689a1308200a33b8722dc08e3b0f6eee03.jpg",width:704,height:528}},episodes:8,ca